    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm Reference="@References[index]"
                           CanRemove="@(References.Count > 2)"
                           OnReferenceChanged="r => UpdateReference(index, r)"
                           OnRemove="() => RemoveReference(index)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? InitialReferences { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (InitialReferences is not null && InitialReferences.Count > 0)
        {
            References = InitialReferences.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new Reference("", "", "", ""));
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(References.ToList());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

