{"file_text": "@page "/apply"
@using sv_d7e993905c8d4dafb232a65611fef4bc.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="@personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep History="@workHistory"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep InitialReferences="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep InitialText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        Work="@workHistory"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEditSection="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string coverLetter = "";

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory history)
    {
        workHistory = history;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 0 && step < currentStep)
            currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            personalInfo!,
            workHistory!,
            references!,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
", "path": "/tmp/sv-d7e993905c8d4dafb232a65611fef4bc/Components/Pages/Apply/Apply.razor"}

