.step-label {
    font-size: 0.75rem;
    color: #6c757d;
    text-align: center;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.dimmed .step-label {
    color: #adb5bd;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #dee2e6;
    align-self: center;
    margin-bottom: 1rem;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: white;
