.entry-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.entry-card h4 {
    margin: 0 0 1rem 0;
    font-size: 1rem;
    color: #495057;
}

