}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-entry:last-child {
    border-bottom: none;
}

.text-muted {
    color: #6c757d;
    font-size: 0.85rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #495057;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #198754;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.05rem;
    color: #495057;
}

