+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-primary {
+    background: #0d6efd;
+    color: white;
+    border: none;
+    padding: 0.6rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-primary:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-outline {
+    background: white;
+    color: #0d6efd;
+    border: 1px solid #0d6efd;
+    padding: 0.6rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+.btn-outline:hover {
+    background: #f0f7ff;
+}
+
+.btn-secondary {
+    background: #f8f9fa;
+    color: #495057;
+    border: 1px solid #dee2e6;
+    padding: 0.5rem 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    margin-top: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #e9ecef;
+}
+
+.btn-remove {
+    background: none;
+    color: #dc3545;
+    border: 1px solid #dc3545;
+    padding: 0.35rem 0.75rem;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    margin-top: 0.5rem;
+}
+
+.btn-remove:hover {
+    background: #dc3545;
+    color: white;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #0d6efd;
+    cursor: pointer;
+    font-size: 0.9rem;
+    text-decoration: underline;
+    padding: 0;
+}
+
+.btn-link:hover {
+    color: #0b5ed7;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.05rem;
+}
+
+/* Entry Cards */
+.entry-card {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafbfc;
+}
+
+.entry-card h4 {
+    margin: 0 0 1rem 0;
+    font-size: 1rem;
+    color: #495057;
+}
+
+/* Error Messages */
+.error-message {
+    background: #f8d7da;
+    color: #842029;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-bottom: 1rem;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #dc3545;
+    font-size: 0.8rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+/* Character Count */
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.5rem;
+}
+
+.char-count.over-limit {
+    color: #dc3545;
+    font-weight: 600;
+}
+
+.cover-letter-input {
+    min-height: 250px;
+    resize: vertical;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #1a1a2e;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 100px 1fr;
+    gap: 0.35rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #6c757d;
+    font-size: 0.9rem;
+}
+
+.review-section dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.text-muted {
+    color: #6c757d;
+    font-size: 0.85rem;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    color: #495057;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h3 {
+    color: #198754;
+    font-size: 1.5rem;
+    margin-bottom: 1rem;
+}
+
+.confirmation p {
+    font-size: 1.05rem;
+    color: #495057;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator {
+        gap: 0.1rem;
+    }
+
+    .step {
+        min-width: 60px;
+        padding: 0.25rem;
+    }
+
+    .step-label {
+        font-size: 0.65rem;
+    }
+
+    .step-connector {
+        width: 15px;
+    }
+}
