@using sv_d7e993905c8d4dafb232a65611fef4bc.Models

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(new WorkEntry((string?)e.Value ?? "", Entry.Title, Entry.StartDate, Entry.EndDate, Entry.Description));

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(new WorkEntry(Entry.Company, (string?)e.Value ?? "", Entry.StartDate, Entry.EndDate, Entry.Description));

    private Task OnStartDateChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(new WorkEntry(Entry.Company, Entry.Title, DateTime.Parse((string?)e.Value ?? ""), Entry.EndDate, Entry.Description));

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, endDate, Entry.Description));
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, Entry.EndDate, (string?)e.Value ?? ""));

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        DateTime? endDate = isCurrent ? null : DateTime.Today;
        return OnEntryChanged.InvokeAsync(new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, endDate, Entry.Description));
    }
}

