        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Reference.Relationship" @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Reference.Email" @onchange="e => Update(Reference with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Reference.Phone" @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? "" })" />
