    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

toolArgs.new_str:
@using sv_d7e993905c8d4dafb232a65611fef4bc.Models

<div class="reference-form">
    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Reference.Name" @onchange="OnNameChanged" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Reference.Relationship" @onchange="OnRelationshipChanged" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Reference.Email" @onchange="OnEmailChanged" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Reference.Phone" @onchange="OnPhoneChanged" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private Task OnNameChanged(ChangeEventArgs e) =>
        OnReferenceChanged.InvokeAsync(new Reference((string?)e.Value ?? "", Reference.Relationship, Reference.Email, Reference.Phone));

    private Task OnRelationshipChanged(ChangeEventArgs e) =>
        OnReferenceChanged.InvokeAsync(new Reference(Reference.Name, (string?)e.Value ?? "", Reference.Email, Reference.Phone));

    private Task OnEmailChanged(ChangeEventArgs e) =>
        OnReferenceChanged.InvokeAsync(new Reference(Reference.Name, Reference.Relationship, (string?)e.Value ?? "", Reference.Phone));

    private Task OnPhoneChanged(ChangeEventArgs e) =>
        OnReferenceChanged.InvokeAsync(new Reference(Reference.Name, Reference.Relationship, Reference.Email, (string?)e.Value ?? ""));
}

